package com.only4u\n\nimport android.content.Context\nimport kotlinx.coroutines.Dispatchers\nimport kotlinx.coroutines.withContext\nimport java.io.File\n\nclass LlamaService(private val context: Context) {\n    private var modelLoaded = false\n    private val modelPath: String by lazy {\n        File(context.getExternalFilesDir(null), \"models\").apply {\n            mkdirs()\n        }.absolutePath\n    }\n\n    init {\n        System.loadLibrary(\"llama_jni\")\n    }\n\n    suspend fun generate(prompt: String): String = withContext(Dispatchers.Default) {\n        if (!modelLoaded) {\n            throw IllegalStateException(\"Model not loaded. Call loadModel first.\")\n        }\n        nativeGenerate(prompt, 128, 0.7f, 0.9f, 40)\n    }\n\n    fun loadModel(modelName: String): Boolean {\n        val file = File(modelPath, modelName)\n        if (!file.exists()) {\n            throw IllegalArgumentException(\"Model file not found: ${file.absolutePath}\")\n        }\n        modelLoaded = nativeLoadModel(file.absolutePath)\n        return modelLoaded\n    }\n\n    fun unloadModel() {\n        if (modelLoaded) {\n            nativeUnloadModel()\n            modelLoaded = false\n        }\n    }\n\n    fun release() {\n        unloadModel()\n    }\n\n    fun getAvailableModels(): List<String> {\n        val modelDir = File(modelPath)\n        return if (modelDir.exists()) {\n            modelDir.listFiles { file ->\n                file.isFile && (file.name.endsWith(\".gguf\") || file.name.endsWith(\".bin\"))\n            }?.map { it.name } ?: emptyList()\n        } else {\n            emptyList()\n        }\n    }\n\n    private external fun nativeLoadModel(modelPath: String): Boolean\n    private external fun nativeUnloadModel()\n    private external fun nativeGenerate(\n        prompt: String,\n        maxTokens: Int,\n        temperature: Float,\n        topP: Float,\n        topK: Int\n    ): String\n}